from pathlib import Path
import html
root=Path(__file__).parent; dist=root/'dist'
nav=[('about.html','About'),('join.html','Schedule / Join'),('operators.html','Operators'),('community.html','Community'),('history.html','Archives'),('resources.html','Resources')]
base='https://web.archive.org/web/'
sources={'home':base+'20181226223857/http://2100net.org/','early':base+'20140516210025/http://2100net.org/','photos':base+'20140629202735/http://2100net.org/pictures.html','script':base+'20180903124807/http://www.2100net.org:80/script.html','history':base+'20140629102429/http://2100net.org/history.html'}
def page(file,title,body):
 links=''.join(f'<a href="{url}"'+(' aria-current="page"' if url==file else '')+f'>{label}</a>' for url,label in nav)
 out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} | 2100 Net</title><meta name="description" content="Connect with Arizona’s 2100 Net. Find joining guidance, net operators, community resources and the recovered 2100net.org archive."><meta name="theme-color" content="#102f36"><link rel="icon" type="image/svg+xml" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Crect width='40' height='40' rx='20' fill='%23102f36'/%3E%3Ctext x='20' y='27' text-anchor='middle' font-family='Arial' font-size='21' fill='%23d8f16d'%3E21%3C/text%3E%3C/svg%3E"><link rel="stylesheet" href="styles.css?v=20261123-images"><script src="site.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="mast"><div class="wrap"><a class="brand" href="index.html" aria-label="2100 Net home"><span class="mark" aria-hidden="true"></span><span><strong>2100 NET</strong><small>ARIZONA · AMATEUR RADIO</small></span></a><button class="menu" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation" aria-label="Main navigation">{links}</nav></div></header><main id="main">{body}</main><footer><div class="wrap"><div><a class="brand" href="index.html"><strong>2100 NET</strong></a><p>A place for familiar voices and new friends. Historical material is dated; contact details are awaiting confirmation.</p></div><div class="footer-links"><a href="join.html">Get on the air</a><a href="history.html">Our archive</a><a href="community.html">Contact</a></div></div></footer></body></html>'''
 (dist/file).write_text(out)
def head(k,t,p):return f'<header class="page-head"><div class="wrap"><div class="eyebrow">{k}</div><h1>{t}</h1><p>{p}</p></div></header>'
page('index.html','Arizona on the air',f'''<section class="hero"><div class="wrap"><div class="hero-copy"><div class="eyebrow">Arizona voices. A nightly tradition.</div><h1>A familiar frequency.<br><em>A new friend.</em></h1><p>Check in, share your day, and get to know the people behind the call signs. Welcome to the 2100 Net.</p><div class="actions"><a class="button" href="join.html">How to join <span aria-hidden="true">↗</span></a><a class="button secondary" href="community.html">Connect with the net</a></div></div><figure class="hero-image"><img src="assets/archive/mtord4b.jpg" alt="Radio towers and microwave dishes at Mount Ord overlooking the Arizona mountains" width="2403" height="1869"><figcaption>MOUNT ORD, ARIZONA · RECOVERED FROM THE ORIGINAL SITE</figcaption></figure></div></section><div class="wrap"><div class="schedule-strip"><div><span class="eyebrow">Listed net time</span><strong>Every night · 9 PM</strong><small>21:00 Mountain Standard Time</small></div><div><span class="eyebrow">On the air</span><strong>ARA Rimlink</strong><small><a href="join.html#repeaters">Find repeater information ↗</a></small></div><div><span class="eyebrow">Arizona time now</span><strong data-arizona-time>MST · UTC−7</strong><small>Confirm tonight’s operation on air.</small></div></div></div><section class="section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Make yourself at home</div><h2>Get your place in the roll call.</h2></div><a href="about.html">Meet the 2100 Net ↗</a></div><div class="cards"><article class="card"><span class="number">01 / FIRST CHECK-IN</span><h3>New to the net? Welcome.</h3><p>Find the listed time, choose a repeater, and learn what to expect when net control calls for visitors.</p><a href="join.html">Your first check-in ↗</a></article><article class="card"><span class="number">02 / PEOPLE & CONNECTIONS</span><h3>Beyond the call sign.</h3><p>Connect on the air, ask about helping with net control, and revisit the faces from our early community.</p><a href="community.html">Find your community ↗</a></article><article class="card"><span class="number">03 / FROM THE ARCHIVE</span><h3>Good company, preserved.</h3><p>Explore recovered photographs, past operator rosters, and the original net’s welcoming spirit.</p><a href="history.html">Explore the archive ↗</a></article></div></div></section><section class="section dark-section"><div class="wrap feature"><div><div class="eyebrow">The spirit of the 2100 Net</div><p class="quote">“You are a friend we have not met yet.”</p><p>A welcome from the original website, preserved as an invitation to the next voice on the air.</p></div><div><h2>Listen. Check in. Say hello.</h2><p>The archived net format starts with roll call, welcomes visitors, then gives everyone a turn to share a little of their day.</p><a class="button" href="join.html">See how the net works ↗</a></div></div></section>''')
page('about.html','About the Net',head('About the net','Good conversation travels.','The 2100 Net brings amateur radio operators together to share the everyday moments that make a community.')+f'''<section class="section"><div class="wrap two-col"><div><h2>A social net with a simple idea.</h2><p>The original 2100net.org welcomed hams to a friendly evening conversation on the Arizona Repeater Association’s Rimlink system. The name comes from its listed start time: 2100 hours, or 9 PM local Mountain Standard Time.</p><p>Net control gives the conversation a rhythm: first check-ins, then a second round for participants to talk about their day. New voices are part of the tradition.</p><h2>More than a list of call signs.</h2><p>The old site connected listeners through photographs, a chat room, streaming audio and pictures of gatherings. This new home preserves those memories while making the essentials easier to find.</p><a class="button" href="join.html">Join the conversation ↗</a><p class="historic">Based on the <a href="{sources['home']}">2018 homepage</a> and <a href="{sources['script']}">archived net script</a>.</p></div><aside class="panel"><div class="eyebrow">The network behind the net</div><h3>Arizona Repeater Association</h3><p>The archived preamble credits ARA’s linked repeaters for making the net possible. Check ARA directly for its current repeater information and operating policies.</p><a href="https://www.w7ara.org/">Visit W7ARA ↗</a></aside></div></section>''')
repeaters=[('McNary, Greens Peak', '146.7200', '−', '162.2'), ('Flagstaff, Mt Elden', '147.1400', '+', '162.2'), ('Globe, Pinal Peak', '147.2000', '+', '162.2'), ('Sunflower, Mt Ord', '147.3600', '+', '162.2'), ('Phoenix, Shaw Butte', '442.8500', '+', '100.0'), ('Aguila, Smith Peak', '443.7750', '+', '100.0'), ('McNary, Greens Peak', '448.3750', '−', '100.0'), ('Cottonwood, Mingus Mtn', '448.5000', '−', '100.0'), ('Globe, Pinal Peak', '927.4125', '−', '151.4')]
rows=''.join('<tr>'+''.join(f'<td>{v}</td>' for v in row)+'</tr>' for row in repeaters)
repeater_accordion=f'''<details class="repeater-details" id="repeaters"><summary>RimLink Repeater Frequencies</summary><p>All repeaters: <strong>W7ARA · Open access · FM · Arizona</strong>.</p><div class="table-scroll" role="region" aria-label="RimLink repeater frequencies" tabindex="0"><table><caption>RimLink repeater frequencies and locations</caption><thead><tr><th scope="col">Location / Site</th><th scope="col">Frequency (MHz)</th><th scope="col">Offset</th><th scope="col">Tone (Hz)</th></tr></thead><tbody>{rows}</tbody></table></div><p><a href="https://www.w7ara.org/z/Repeaters.aspx">Current ARA directory</a></p></details>'''
page('join.html','Schedule and How to Join',head('Your first check-in','We’ll be listening for you.','A few simple steps to find the net and join the conversation.')+f'''<section class="section"><div class="wrap two-col"><div><ol class="steps"><li><h3>Tune in around 9 PM MST.</h3><p>The net is listed nightly at 21:00 MST (UTC−7), on ARA Rimlink. That is 04:00 UTC the following day. Listen for the evening’s opening and any operating changes.</p></li><li><h3>Find your local Rimlink repeater.</h3><p>Use the current ARA directory to confirm frequency, offset, tone and link status for your area. Listen first and follow the repeater’s operating policies.</p>{repeater_accordion}</li><li><h3>Wait for the call for visitors.</h3><p>The archived format begins with regular roll call, followed by late, missed and visiting stations. When invited, give your call sign clearly and follow net control’s directions.</p></li><li><h3>Share a little of your day.</h3><p>In the second round, net control gives each station a turn. Keep it friendly and concise so everyone has time to speak. Emergency or priority traffic takes precedence.</p></li></ol></div><aside class="panel"><div class="eyebrow">Listed schedule</div><h2>21:00 MST</h2><p>Every night · Arizona time</p><p class="note">This is the archived schedule, also listed by Kachina Amateur Radio Club. Confirm tonight’s operation on air. See the <a href="operators.html">weekly net control roster</a>.</p><a href="https://kachinaarc.org/nets/">View club net listing ↗</a><h3>Just listening?</h3><p>You can <a href="https://www.broadcastify.com/listen/feed/19249" target="_blank">listen online</a></p></aside></div></section><section class="section" id="repeater-map"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Get connected</div><h2>Choose a repeater.</h2></div><a class="button" href="https://www.w7ara.org/z/Repeaters.aspx">Current ARA directory ↗</a></div><figure style="margin:1.5rem 0"><img src="assets/rimlink-sites.svg" width="630" height="690" style="display:block;width:100%;max-width:630px;height:auto" alt="Arizona map locating the seven mountain sites listed in the repeater accordion"><figcaption>Approximate mountain locations. Greens Peak and Pinal Peak each host two listed frequencies.</figcaption></figure></div></section>''')
operator_schedule = [
    ('Monday', 'Hal', 'KG5LVG'),
    ('Tuesday', 'Lucas', 'K7ETV'),
    ('Wednesday', 'Lydianne', 'W7LYD'),
    ('Thursday', 'Bob', 'AB7RR'),
    ('Friday', 'Dwayne', 'AE7DH'),
    ('Saturday', 'Joe', 'AE7JG'),
    ('Sunday', 'Mike', 'KK7PUG'),
]
operator_rows = ''.join(
    f'<tr><th scope="row">{day}</th><td>{name}</td><td>{callsign}</td></tr>'
    for day, name, callsign in operator_schedule
)
page('operators.html','Net Operators',head('The voices at net control','Keeping the conversation going.','Net control welcomes stations, guides the roll call, and makes room for everyone to take a turn.')+f'''<section class="section"><div class="wrap two-col"><div><h2>Weekly net control schedule</h2><div class="table-scroll"><table><caption>2100 Net operators by day</caption><thead><tr><th scope="col">Day</th><th scope="col">Operator</th><th scope="col">Call sign</th></tr></thead><tbody>{operator_rows}</tbody></table></div></div><aside class="panel"><div class="eyebrow">Operator resources</div><h3>The original net format</h3><p>Opening and priority-traffic check, regular roll call, visitors, a second round of conversation, and closing thanks to participants and ARA.</p><a href="{sources['script']}">Read the archived script ↗</a><h3>2100NetLog</h3><p>The companion logging project supports roll call, a second-round queue, trivia, printable logs and public net pages. A public address has not been configured for this site yet.</p></aside></div></section>''')
page('community.html','Community and Contact',head('Community / Contact','Start with a hello.','The net is a place to meet people, swap experiences, and help the next person get on the air.')+'''<section class="section"><div class="wrap"><div class="cards"><article class="card"><span class="number">ON THE AIR</span><h3>Talk with the operators.</h3><p>Check in when visitors are invited. Ask net control about volunteering, getting help, or arranging a conversation after the net.</p><a href="join.html">See how to check in ↗</a></article><article class="card"><span class="number">IN THE COMMUNITY</span><h3>Find a familiar call sign.</h3><p>Revisit the original “Face to the Voice” gallery, or use QRZ to look up a station you heard on the air.</p><a href="gallery.html">Explore the photo archive ↗</a></article><article class="card"><span class="number">AROUND ARIZONA</span><h3>Meet beyond the radio.</h3><p>Visit the Amateur Radio Council of Arizona for regional clubs and ham-radio events.</p><a href="https://arca-az.org/">Visit the Arizona council ↗</a></article></div><div class="note"><strong>Website contact details are being updated.</strong> A current operator email address has not been confirmed. The old email addresses, chat room and streaming service are not presented as working contact channels.</div><div class="two-col"><div><h2>Have a photo or a memory?</h2><p>Keep a copy of the image, the names or call signs you recognize, and an approximate date. Once the current website contact is confirmed, those details will help connect the story to the archive.</p><h3>Need a photo corrected or removed?</h3><p>The original gallery welcomed correction and removal requests. Until a current website contact is available, ask net control how to reach the site’s maintainer. The recovered pictures here are labeled as historical, not a current member directory.</p></div><aside class="panel"><h3>Good conversations start here.</h3><p>Give others room to speak, follow net control’s lead, and ask before sharing someone else’s personal details. Welcome unfamiliar call signs as warmly as familiar ones.</p><a href="https://www.qrz.com/">Open QRZ’s call-sign directory ↗</a></aside></div></div></section>''')
page('history.html','History and Archives',head('History / Archives','The voices came first.','Photographs, familiar call signs, and the story of a website built to bring people together.')+f'''<section class="section"><div class="wrap feature"><figure><img src="assets/archive/mtord4b.jpg" alt="Mount Ord communications towers from the original 2100net.org website" width="2403" height="1869"><figcaption>Mount Ord photograph recovered from the December 2018 homepage. Original photographer not identified.</figcaption></figure><div><span class="pill">RECOVERED FROM WAYBACK</span><h2>A little of the old site,<br>a lot of familiar faces.</h2><p>The original website put a face to the voice, shared pictures of gatherings, and helped visitors find the evening net. Its pages are preserved here as a record of the community.</p><a class="button" href="gallery.html">Browse the recovered gallery ↗</a></div></div></section><section class="section"><div class="wrap two-col"><div><h2>Pages from the past</h2><div class="timeline"><article><div class="eyebrow">May 2014</div><h3>A welcoming home on the web</h3><p>The earliest homepage capture lists three rotating operators, Rimlink repeaters, a chat room, audio streaming, member photos and Sunday coffee gatherings in Tempe. The page credits “Daddy Cool” and says it was updated April 1, 2014.</p><a href="{sources['early']}">Open the 2014 homepage ↗</a></article><article><div class="eyebrow">June 2014</div><h3>Putting a face to the voice</h3><p>The gallery pairs call signs with member photographs. The history page discusses an old 1AW QSL card and the beginnings of ARRL, with its ARRL account attributed to Wikipedia.</p><a href="{sources['photos']}">View the original gallery ↗</a> · <a href="{sources['history']}">Read the old history page ↗</a></article><article><div class="eyebrow">September–December 2018</div><h3>A fuller record of the net</h3><p>The later site adds a net-control script, volunteer guidance and a gallery of social gatherings. The homepage’s operator rotation has changed and several days are marked open.</p><a href="{sources['home']}">Open the 2018 homepage ↗</a> · <a href="{sources['script']}">Read the operator script ↗</a></article></div></div><aside class="panel"><h3>About this recovery</h3><p>Wayback’s calendar showed 25 homepage captures from May 2014 to September 2026, and 448 captured URLs under this prefix.</p><p>The December 26, 2018 homepage is the most useful of the homepage versions inspected. September 2018 subpages and the June 2014 gallery supplement it. The newest homepage capture redirects away from the net.</p><p>Some images were missing. No old chat or audio service has been reactivated. The archive is a historical record, not a current operating directory.</p><a href="recovery.html">What was recovered and changed ↗</a></aside></div></section>''')
photos=[('ke7euttl.jpg','KE7EUL','Travis'),('Kf7dedtt.jpg','KF7DED','Larry'),('Kf7wwptt.jpg','KF7WWP','Roger'),('kg7fxttt.JPG','KG7FXT','Thomas'),('ki6ahhtt.jpg','KI6AHH','Tony'),('AC7AMt.jpg','AC7AM','Tom'),('W7QHZtt.jpg','W7QHZ','Martin'),('wb2maatt.JPG','WB2MAA','Richard'),('ke7htltt.jpg','KE7HTL','Ed'),('n7nnlt.jpg','N7NNL','Paulette'),('kd7awwt.jpg','KD7AWW','Alice'),('NT9Bt.jpg','NT9B','Jim'),('k2dfet.jpg','K2DFE','Jeff'),('N7OXF3t.jpg','N7OXF','Dale & Kristy'),('kf7sfgt.jpg','KF7SFG','David'),('kf7rwvt.jpg','KF7RWV','Ellis'),('kg7gtht.jpg','WB4CVO','Tom'),('Kg7elrt.jpg','W7DGL','Doug'),('kc7mbrt.jpg','KC7MBR','Butch')]
gallery=''.join(f'<figure><a href="assets/archive/{file}" aria-label="Open archived photo of {html.escape(name)}, {call}"><img src="assets/archive/{file}" alt="Archived photograph labeled {html.escape(name)}, {call}" loading="lazy" width="200" height="180"></a><figcaption><strong>{call}</strong> · {html.escape(name)}<small>From the 2014 gallery</small></figcaption></figure>' for file,call,name in photos)
page('gallery.html','Face to the Voice — Photo Archive',head('The photo archive / 2014','Putting a face to the voice.','Nineteen photographs recovered from the early 2100 Net gallery, with the original call-sign captions.')+f'''<section class="section"><div class="wrap"><p class="note">Historical photographs and labels from the June 29, 2014 capture. These do not indicate current membership, current call signs, or operator assignments. Images are shown at their recovered resolution.</p><div class="gallery">{gallery}</div><p class="historic">Source: <a href="{sources['photos']}">original “Face to the Voice” gallery</a>. Photographer credits were not specified on the recovered page. Four member thumbnails could not be recovered: N7BBS, W7ADO, W1VBG/W7YKU and WX7JEM. <a href="community.html">Corrections and removal guidance</a>.</p></div></section>''')
resources=[('https://www.w7ara.org/z/Repeaters.aspx','ARA repeater directory','Confirm repeater frequencies, sites and system details with the network operator.'),('https://www.w7ara.org/','Arizona Repeater Association','Learn about the organization behind the linked repeater system.'),('https://www.arrl.org/','ARRL','Explore amateur radio, license education, operating resources and clubs.'),('https://www.qrz.com/','QRZ call-sign directory','Look up a station you heard on the net. Some services require an account.'),('https://arca-az.org/','Amateur Radio Council of Arizona','Find Arizona amateur-radio organizations and regional events.'),('https://kachinaarc.org/nets/','Kachina ARC net listings','Explore other nets and the club’s listing for the 2100 Net.')]
links=''.join(f'<a class="resource" href="{url}"><span><strong>{title}</strong><p>{desc}</p></span><span aria-hidden="true">↗</span></a>' for url,title,desc in resources)
page('resources.html','Ham Radio Resources',head('Useful ham-radio resources','A few good places to start.','Find repeater information, look up a call sign, and discover the wider Arizona amateur-radio community.')+f'<section class="section"><div class="wrap content">{links}<p class="historic">The original site linked to ARA-related repeater information, ARRL, QRZ and Arizona ham events. This shorter directory points to current organization websites instead of copying the old catalog of commercial links.</p></div></section>')
page('recovery.html','Recovery Notes',head('Archive provenance','Recovered. Reorganized. Reconnected.','A record of what survived, where it came from, and how it shaped the new website.')+f'''<section class="section"><div class="wrap content"><h2>Selected snapshots</h2><ul><li><a href="{sources['early']}">May 16, 2014 homepage</a>: earliest available homepage in the calendar; clear welcome, roster, frequency list and original navigation.</li><li><a href="{sources['photos']}">June 29, 2014 gallery</a>: names, call signs and 19 recoverable member thumbnails.</li><li><a href="{sources['home']}">December 26, 2018 homepage</a>: fuller navigation, operator recruitment, updated roster and Mount Ord photograph; page marked updated September 12, 2018.</li><li><a href="{sources['script']}">September 3, 2018 operator script</a>: roll call, visitors, second round and closing; page marked updated June 5, 2016.</li></ul><p>The September 16, 2026 homepage capture redirected to an unrelated travel domain and was excluded. Selection reflects the useful versions inspected, not a claim that every capture was exhaustively audited.</p><h2>Recovered assets</h2><p>24 image files: 19 member thumbnails, two gathering thumbnails, two banner GIFs and the Mount Ord photograph. Original binaries and a source manifest are included with the project. Six attempted gallery assets were unavailable or returned invalid image responses.</p><h2>What changed</h2><ul><li>Table-based navigation became semantic, responsive pages with keyboard navigation and visible focus states.</li><li>Joining instructions, operator information, community guidance and archive material have separate destinations.</li><li>Outdated repeater settings and rosters are explicitly historical; current repeater guidance links to ARA.</li><li>The historic gallery has readable captions and alternative text.</li><li>Obsolete chat, stream embeds, old contact addresses and repeater-control codes are not active features.</li><li>The rebuilt site runs without third-party scripts, external fonts or a database.</li></ul><h2>What still needs confirmation</h2><p>Current contact information, a supported streaming or chat service, and a public address for 2100NetLog. No contact form pretends to send messages, and no sample members or live net status have been invented.</p><h2>Logging integration</h2><p>The local 2100NetLog project already provides public net pages and protected operator tools. This site is an independent community front end. A future link to its public pages can connect visitors to live and past net sessions without exposing private station records.</p><a href="history.html">Back to the archive ↗</a></div></section>''')

# Append recovered gathering history to the archive without changing the shared layout.
p=dist/'history.html'
s=p.read_text().replace('</main>','''<section class="section"><div class="wrap"><div class="eyebrow">Beyond the repeater</div><h2>From hamfests to Field Day.</h2><p>The 2018 social page records coffee mornings in Tempe, a July 2014 Payson gathering, Arizona hamfests, station projects and Field Day at the Arizona Science Center in June 2015. These are past events, not upcoming invitations.</p><div class="gallery"><figure><a href="assets/archive/Payson_Visit_1t.jpg"><img src="assets/archive/Payson_Visit_1t.jpg" alt="Archived group photograph from the July 2014 Payson gathering" loading="lazy" width="200" height="180"></a><figcaption>Payson gathering<small>July 2014 · original site caption</small></figcaption></figure><figure><a href="assets/archive/ascfd1t.jpg"><img src="assets/archive/ascfd1t.jpg" alt="Archived Field Day photograph from the Arizona Science Center" loading="lazy" width="200" height="180"></a><figcaption>Field Day at C.A.R.L.<small>June 2015 · Arizona Science Center</small></figcaption></figure></div><p><a href="https://web.archive.org/web/20180903124901/http://2100net.org/being_social.html">View the original social archive ↗</a></p></div></section></main>''')
p.write_text(s)
# Explicit, opt-in integration. Unknown destinations remain absent from public links.
import json,re
from urllib.parse import urlparse
config=json.loads((root/'site-config.json').read_text())
log_url=config.get('logBaseUrl')
email=config.get('contactEmail')
if log_url:
 parsed=urlparse(log_url)
 if parsed.scheme!='https' or not parsed.netloc or parsed.username or parsed.password or parsed.query or parsed.fragment:
  raise ValueError('logBaseUrl must be an HTTPS origin or base path without credentials, query or fragment')
 url=html.escape(log_url.rstrip('/'),quote=True)
 p=dist/'operators.html';s=p.read_text().replace('A public address has not been configured for this site yet.','Public net pages and operator tools are available in the companion app.')
 s=s.replace('</aside>',f'<div class="actions"><a class="button" href="{url}/public/nets">View public nets ↗</a><a href="{url}/nets">Operator sign-in ↗</a></div></aside>');p.write_text(s)
 p=dist/'history.html';p.write_text(p.read_text().replace('</main>',f'<section class="section"><div class="wrap"><h2>Net session history</h2><a class="button" href="{url}/public/nets?scope=all">Browse the public net log ↗</a></div></section></main>'))
if email:
 if not re.fullmatch(r'[A-Za-z0-9.!#$%&*+/=?^_`{|}~-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}',email):
  raise ValueError('contactEmail must be a single email address')
 p=dist/'community.html';s=p.read_text();start=s.index('<div class="note">');end=s.index('</div>',start)+6
 s=s[:start]+f'<div class="note"><strong>Contact the website team.</strong> <a href="mailto:{html.escape(email,quote=True)}">{html.escape(email)}</a>. Include your call sign and the reason for your message.</div>'+s[end:]
 s=s.replace('Once the current website contact is confirmed, those details will help connect the story to the archive.','Email those details to the website team to help connect the story to the archive.').replace('Until a current website contact is available, ask net control how to reach the site’s maintainer.','Email the website team with the photo’s caption and your requested correction or removal.');p.write_text(s)
